package main

import "fmt"

// This file demonstrates module concepts.
// In a real project you would have a go.mod file.

// Simulated version info from a hypothetical go.mod
const moduleVersion = "v1.0.0"
const moduleName = "github.com/example/learngo"

func printModuleInfo() {
	fmt.Printf("Module: %s\n", moduleName)
	fmt.Printf("Version: %s\n", moduleVersion)
}

// Semantic version parser
func parseVersion(v string) (major, minor, patch int) {
	// TODO: parse "v1.2.3" format and return 1, 2, 3
	// Hint: use fmt.Sscanf(v, "v%d.%d.%d", &major, &minor, &patch)
	fmt.Sscanf(v, "v%d.%d.%d", &major, &minor, &patch)
	return
}

func main() {
	printModuleInfo()

	maj, min, pat := parseVersion("v2.5.13")
	fmt.Printf("Major: %d, Minor: %d, Patch: %d\n", maj, min, pat)
}
